package com.cryptoaipro.monitor

import android.content.Context
import org.json.JSONObject
import kotlin.math.exp
import kotlin.math.tanh

/**
 * Inference-only 10-member MLP ensemble trained from historical Binance USD-M Futures candles.
 * The weights are generated by tools/train_wolf_ensemble.py and packaged as an Android asset.
 */
internal object WolfPretrainedEnsemble {
    data class Status(val loaded: Boolean, val members: Int, val samples: Int, val trainedAt: String, val testAccuracy: Double)
    private data class Member(val w1:Array<DoubleArray>,val b1:DoubleArray,val w2:Array<DoubleArray>,val b2:DoubleArray,val w3:DoubleArray,val b3:Double)
    @Volatile private var members:List<Member> = emptyList()
    @Volatile private var mean=DoubleArray(7)
    @Volatile private var scale=DoubleArray(7){1.0}
    @Volatile private var status=Status(false,0,0,"",0.0)

    @Synchronized fun initialize(context:Context):Status {
        if(status.loaded) return status
        runCatching {
            val j=JSONObject(context.assets.open("wolf_pretrained_ensemble.json").bufferedReader().use{it.readText()})
            require(j.optString("format")=="amir-wolf-ensemble-v1")
            fun vector(a:org.json.JSONArray)=DoubleArray(a.length()){a.getDouble(it)}
            fun matrix(a:org.json.JSONArray)=Array(a.length()){r->vector(a.getJSONArray(r))}
            val loaded=j.getJSONArray("members")
            members=(0 until loaded.length()).map { i ->
                val m=loaded.getJSONObject(i)
                Member(matrix(m.getJSONArray("w1")),vector(m.getJSONArray("b1")),matrix(m.getJSONArray("w2")),
                    vector(m.getJSONArray("b2")),vector(m.getJSONArray("w3")),m.getDouble("b3"))
            }
            mean=vector(j.getJSONArray("feature_mean")); scale=vector(j.getJSONArray("feature_scale")).map{if(it==0.0)1.0 else it}.toDoubleArray()
            val metrics=j.getJSONArray("metrics")
            val acc=(0 until metrics.length()).map{metrics.getJSONObject(it).optDouble("accuracy",0.0)}.average()
            status=Status(members.size==10,members.size,j.optInt("samples"),j.optString("trained_at_utc"),acc)
        }.onFailure { status=Status(false,0,0,"",0.0) }
        return status
    }

    fun status()=status
    fun predict(signal:MarketSignal):Double? {
        if(members.size!=10) return null
        val t=signal.technical
        val direction=if(signal.direction=="SHORT_BIAS") -1.0 else 1.0
        val trend=if(t.ema20>=t.ema50) 1.0 else -1.0
        val rsi=((signal.rsi-50.0)/50.0).coerceIn(-1.0,1.0)
        val adx=(t.adx/50.0).coerceIn(0.0,1.0)
        val volume=((t.relativeVolume-1.0)/2.0).coerceIn(-1.0,1.0)
        val candle=signal.candles.lastOrNull()
        val body=if(candle!=null && candle.size>=4) (candle[3]-candle[0])/((candle[1]-candle[2]).coerceAtLeast(1e-9)) else 0.0
        val bodyFeature=when { body>.25 -> 1.0; body<-.25 -> -1.0; else -> 0.0 }
        val volatility=((t.atrPercent-2.0)/5.0).coerceIn(-1.0,1.0)
        val raw=doubleArrayOf(trend*direction,rsi*direction,adx,volume,bodyFeature*direction,volatility,(signal.score/100.0).coerceIn(-1.0,1.0))
        val x=DoubleArray(7){i->((raw[i]-mean[i])/scale[i]).coerceIn(-8.0,8.0)}
        val outputs=members.map { m ->
            val h1=DoubleArray(m.b1.size){i->tanh(m.b1[i]+x.indices.sumOf{j->m.w1[i][j]*x[j]})}
            val h2=DoubleArray(m.b2.size){i->tanh(m.b2[i]+h1.indices.sumOf{j->m.w2[i][j]*h1[j]})}
            val z=m.b3+h2.indices.sumOf{j->m.w3[j]*h2[j]}
            1.0/(1.0+exp(-z.coerceIn(-30.0,30.0)))
        }
        return outputs.average().coerceIn(0.01,0.99)
    }
}
